class Task:
    def __init__(self, id, wcet, period, processor_id, priority, resource_accesses):
        self.id = id
        self.e = wcet
        self.p = period
        self.u = self.e / self.p
        self.processor_id = processor_id
        self.pi = priority
        self.N_q = resource_accesses # Dictionary {q_id: max_accesses}
        self.L_q = {} # Dictionary {q_id: max_cs_length}
        self.r = 0 # Worst-case response time (to be computed)

class Resource:
    def __init__(self, id, type): # type: 'local' or 'global'
        self.id = id
        self.type = type

def system_setup(tasks, resources, num_processors):
    # Initialize tasks and resources based on input parameters
    # ...
    pass

def compute_resource_ceiling(resource_q, tasks):
    min_priority = float('inf')
    for task_i in tasks:
        if task_i.N_q.get(resource_q.id, 0) > 0 and resource_q.type == 'local':
            min_priority = min(min_priority, task_i.pi)
    return min_priority if min_priority != float('inf') else None

def compute_dynamic_system_ceiling(current_locked_resources, tasks):
    max_resource_ceiling = float('inf')
    for resource_q in current_locked_resources:
        ceiling = compute_resource_ceiling(resource_q, tasks)
        if ceiling is not None:
            max_resource_ceiling = min(max_resource_ceiling, ceiling)
    return max_resource_ceiling if max_resource_ceiling != float('inf') else len(tasks) + 1

def calculate_beta_loc_i(task_i, tasks, resources):
    max_L_l_q = 0
    for task_l in tasks:
        if task_l.processor_id == task_i.processor_id and task_l.pi > task_i.pi:
            for q_id, L_l_q_val in task_l.L_q.items():
                resource_q = next((r for r in resources if r.id == q_id), None)
                if resource_q and resource_q.type == 'local':
                    pi_q = compute_resource_ceiling(resource_q, tasks)
                    if pi_q is not None and pi_q <= task_i.pi:
                        max_L_l_q = max(max_L_l_q, L_l_q_val)
    return max_L_l_q

def calculate_S_i_q(task_i, resource_q, tasks, num_processors):
    if task_i.N_q.get(resource_q.id, 0) == 0:
        return 0
    spin_time = 0
    for pk in range(num_processors):
        if pk != task_i.processor_id:
            max_L_x_q_on_pk = 0
            for task_x in tasks:
                if task_x.processor_id == pk:
                    max_L_x_q_on_pk = max(max_L_x_q_on_pk, task_x.L_q.get(resource_q.id, 0))
            spin_time += max_L_x_q_on_pk
    return spin_time

def calculate_beta_rem_i(task_i, resources, tasks, num_processors):
    total_remote_blocking = 0
    for q_id, N_i_q_val in task_i.N_q.items():
        resource_q = next((r for r in resources if r.id == q_id), None)
        if resource_q and resource_q.type == 'global':
            S_i_q_val = calculate_S_i_q(task_i, resource_q, tasks, num_processors)
            total_remote_blocking += N_i_q_val * S_i_q_val
    return total_remote_blocking

def calculate_e_h_inflated(task_h, resources, tasks, num_processors):
    beta_rem_h = calculate_beta_rem_i(task_h, resources, tasks, num_processors)
    return task_h.e + beta_rem_h

def calculate_beta_NP_i(task_i, tasks, resources, num_processors):
    max_NP_blocking = 0
    for task_l in tasks:
        if task_l.processor_id == task_i.processor_id and task_l.pi > task_i.pi:
            for q_id, L_l_q_val in task_l.L_q.items():
                resource_q = next((r for r in resources if r.id == q_id), None)
                if resource_q and resource_q.type == 'global':
                    S_l_q_val = calculate_S_i_q(task_l, resource_q, tasks, num_processors)
                    max_NP_blocking = max(max_NP_blocking, S_l_q_val + L_l_q_val)
    return max_NP_blocking

def get_local_higher_priority_tasks(task_i, all_tasks):
    return [t for t in all_tasks if t.processor_id == task_i.processor_id and t.pi < task_i.pi]

def get_local_lower_priority_tasks(task_i, all_tasks):
    return [t for t in all_tasks if t.processor_id == task_i.processor_id and t.pi > task_i.pi]

def get_local_resources_on_processor(processor_id, all_resources):
    return [r for r in all_resources if r.processor_id == processor_id and r.type == 'local'] # Assuming resources have processor_id if local

def get_global_resources(all_resources):
    return [r for r in all_resources if r.type == 'global']

def compute_conflict_set(task_i, local_resources, tasks):
    conflict_set = []
    for q in local_resources:
        pi_q = compute_resource_ceiling(q, tasks) # Re-use MSRP_ResourceCeilings definition
        if pi_q is not None and pi_q <= task_i.pi:
            conflict_set.append(q.id)
    return conflict_set

def njobs(task_x, interval_t):
    # r_x would be the current estimate of task_x.r in an iterative process
    return math.ceil((interval_t + task_x.r) / task_x.p)

def N_i_x_q(task_i, task_x, resource_q, all_tasks):
    # Assuming task_i.r is known (iteratively)
    return njobs(task_x, task_i.r) * task_x.N_q.get(resource_q.id, 0)

def ncs_T_i_q(task_i, resource_q, all_tasks):
    count = task_i.N_q.get(resource_q.id, 0)
    tau_lh = get_local_higher_priority_tasks(task_i, all_tasks)
    for t_h in tau_lh:
        count += N_i_x_q(task_i, t_h, resource_q, all_tasks)
    return count

def analyze_with_inflation(task_set):
    # This pseudocode illustrates the *problem*, not the solution.
    for task_h in task_set:
        task_h.e_inflated = task_h.e + calculate_beta_rem_i(task_h, ...)

    for task_i in task_set:
        response_time_i = task_i.e
        # ... other blocking terms ...
        for task_h in get_local_higher_priority_tasks(task_i, task_set):
            # The inflated cost is repeatedly added
            response_time_i += math.ceil(response_time_i / task_h.p) * task_h.e_inflated
        # ...
    return response_time_i

def apply_constraint_1(blocking_variables):
    # blocking_variables is a dictionary of (T_x, q, v) -> {'X_A': val, 'X_S': val}
    for (tx_id, q_id, v_id), vars in blocking_variables.items():
        # In an ILP solver, this would be a direct constraint:
        # X_A_tx_q_v + X_S_tx_q_v <= 1
        if vars['X_A'] + vars['X_S'] > 1:
            raise ValueError(f"Constraint 1 violated for ({tx_id}, {q_id}, {v_id})")

def apply_constraint_2(arrival_blocking_indicators):
    # arrival_blocking_indicators is a dictionary {q_id: A_q_val}
    # In an ILP solver, this would be a direct constraint:
    # sum(A_q) <= 1
    if sum(arrival_blocking_indicators.values()) > 1:
        raise ValueError("Constraint 2 violated: More than one resource caused arrival blocking.")

def apply_constraint_3(arrival_blocking_indicators, tasks, resources, task_i):
    tau_ll = get_local_lower_priority_tasks(task_i, tasks)
    for q_id, A_q_val in arrival_blocking_indicators.items():
        if A_q_val == 1:
            total_N_x_q = 0
            for t_x in tau_ll:
                total_N_x_q += t_x.N_q.get(q_id, 0)
            # In an ILP solver, this would be A_q <= sum(N_x_q for T_x in tau_ll)
            if total_N_x_q == 0:
                raise ValueError(f"Constraint 3 violated: A_q is 1 for {q_id} but no local lower-priority tasks access it.")

def apply_constraint_4(arrival_blocking_indicators, task_i, local_resources, conflict_set_ids):
    for q in local_resources:
        if q.id not in conflict_set_ids:
            # In an ILP solver, this would be A_q <= 0
            if arrival_blocking_indicators.get(q.id, 0) > 0:
                raise ValueError(f"Constraint 4 violated: A_q is > 0 for local resource {q.id} not in conflict set.")

def apply_constraint_5(blocking_variables, task_i, tasks):
    tau_lh = get_local_higher_priority_tasks(task_i, tasks)
    total_XA_from_tau_lh = 0
    for (tx_id, q_id, v_id), vars in blocking_variables.items():
        task_x = next((t for t in tasks if t.id == tx_id), None)
        if task_x in tau_lh:
            total_XA_from_tau_lh += vars['X_A']
    # In an ILP solver, this would be sum(X_A_x_q_v for T_x in tau_lh) <= 0
    if total_XA_from_tau_lh > 0:
        raise ValueError("Constraint 5 violated: Arrival blocking attributed to local higher-priority tasks.")

def apply_constraint_6(blocking_variables, arrival_blocking_indicators, tasks, task_i):
    tau_ll = get_local_lower_priority_tasks(task_i, tasks)
    for q_id, A_q_val in arrival_blocking_indicators.items():
        sum_XA_for_q = 0
        for t_x in tau_ll:
            for v in range(1, N_i_x_q(task_i, t_x, {'id': q_id}, tasks) + 1):
                sum_XA_for_q += blocking_variables.get((t_x.id, q_id, v), {'X_A': 0})['X_A']
        # In an ILP solver, this would be sum(X_A_x_q_v for T_x in tau_ll) <= A_q
        if sum_XA_for_q > A_q_val:
            raise ValueError(f"Constraint 6 violated for {q_id}: Sum of X_A ({sum_XA_for_q}) exceeds A_q ({A_q_val}).")

def apply_constraint_7(blocking_variables, task_i, tasks):
    local_tasks = get_local_higher_priority_tasks(task_i, tasks) + get_local_lower_priority_tasks(task_i, tasks)
    total_XS_from_local_tasks = 0
    for (tx_id, q_id, v_id), vars in blocking_variables.items():
        task_x = next((t for t in tasks if t.id == tx_id), None)
        if task_x in local_tasks:
            total_XS_from_local_tasks += vars['X_S']
    # In an ILP solver, this would be sum(X_S_x_q_v for T_x in tau_ll U tau_lh) <= 0
    if total_XS_from_local_tasks > 0:
        raise ValueError("Constraint 7 violated: Spin delay attributed to local tasks.")

def apply_constraint_8(blocking_variables, task_i, tasks, resources, num_processors):
    for pk in range(num_processors):
        tau_P_k = [t for t in tasks if t.processor_id == pk]
        for q in resources:
            ncs_val = ncs_T_i_q(task_i, q, tasks) # From ILP_AuxiliarySetsAndFunctions
            sum_XS_on_pk_for_q = 0
            for t_x in tau_P_k:
                for v in range(1, N_i_x_q(task_i, t_x, q, tasks) + 1):
                    sum_XS_on_pk_for_q += blocking_variables.get((t_x.id, q.id, v), {'X_S': 0})['X_S']
            # In an ILP solver, this would be sum(X_S_x_q_v for T_x in tau_P_k) <= ncs_T_i_q
            if sum_XS_on_pk_for_q > ncs_val:
                raise ValueError(f"Constraint 8 violated for P_k={pk}, q={q.id}: Sum of X_S ({sum_XS_on_pk_for_q}) exceeds ncs ({ncs_val}).")

def is_task_schedulable(task_i, calculated_r_i):
    return calculated_r_i <= task_i.p

def check_system_schedulability(tasks, response_times_map):
    for task_i in tasks:
        if not is_task_schedulable(task_i, response_times_map[task_i.id]):
            print(f"Task {task_i.id} is NOT schedulable (r_i={response_times_map[task_i.id]}, p_i={task_i.p})")
            return False
    print("All tasks are schedulable.")
    return True
